package in.guvi.fraud.dao;
import in.guvi.fraud.db.Database;import in.guvi.fraud.model.Transaction;import java.sql.*;import java.time.LocalDateTime;import java.util.*;
public class TransactionDao {
 public void save(Transaction t)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO transactions(customer_id,amount,payment_method,location,created_at,risk_score,decision,explanation) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,t.customerId);p.setBigDecimal(2,t.amount);p.setString(3,t.paymentMethod);p.setString(4,t.location);p.setTimestamp(5,Timestamp.valueOf(t.createdAt));p.setInt(6,t.riskScore);p.setString(7,t.decision);p.setString(8,t.explanation);p.executeUpdate();}}
 public int recent(String id,LocalDateTime time)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM transactions WHERE customer_id=? AND created_at>=? AND created_at<?")){p.setString(1,id);p.setTimestamp(2,Timestamp.valueOf(time.minusHours(1)));p.setTimestamp(3,Timestamp.valueOf(time));try(ResultSet r=p.executeQuery()){return r.next()?r.getInt(1):0;}}}
 public List<Transaction> list(int limit,boolean flagged)throws SQLException{List<Transaction> a=new ArrayList<>();String q="SELECT * FROM transactions "+(flagged?"WHERE decision<>'APPROVED' ":"")+"ORDER BY id DESC LIMIT ?";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,limit);try(ResultSet r=p.executeQuery()){while(r.next()){Transaction t=new Transaction();t.id=r.getLong("id");t.customerId=r.getString("customer_id");t.amount=r.getBigDecimal("amount");t.paymentMethod=r.getString("payment_method");t.location=r.getString("location");t.createdAt=r.getTimestamp("created_at").toLocalDateTime();t.riskScore=r.getInt("risk_score");t.decision=r.getString("decision");t.explanation=r.getString("explanation");t.reviewed=r.getBoolean("reviewed");t.reviewNote=r.getString("review_note");a.add(t);}}}return a;}
 public long count(String where)throws SQLException{try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM transactions "+where)){return r.next()?r.getLong(1):0;}}
 public int setting(String k,int d)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT setting_value FROM settings WHERE setting_key=?")){p.setString(1,k);try(ResultSet r=p.executeQuery()){return r.next()?Integer.parseInt(r.getString(1)):d;}}}
 public void setting(String k,int v)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("MERGE INTO settings KEY(setting_key) VALUES(?,?)")){p.setString(1,k);p.setString(2,""+v);p.executeUpdate();}}
 public void review(long id,String note)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE transactions SET reviewed=TRUE,review_note=? WHERE id=?")){p.setString(1,note);p.setLong(2,id);p.executeUpdate();}}
}
